import { type FC, useMemo, useState } from 'react';

import {
  agentBuilderApi,
  type AgentSpec,
  type MissingResource,
  type ResourceCandidate,
  type ResourcePlan,
  type RiskWarning,
} from '@coze-arch/bot-api';
import { IconCozArrowLeft, IconCozPlus } from '@coze-arch/coze-design/icons';
import { Button, Spin, Tag, TextArea, Toast } from '@coze-arch/coze-design';

export interface AgentBuilderProps {
  spaceId: string;
  onBack?: () => void;
  onCreated?: (botId: string, redirectURL?: string) => void;
}

const EXAMPLE_REQUIREMENTS = [
  '帮我根据参会人数、地点和日程冲突推荐会议室，确认后再生成预订草稿',
  '帮我每天汇总个人待办、逾期任务和优先级，提醒我跟进但不要自动改状态',
  '帮我每周汇总项目进展、里程碑和风险，生成项目周报草稿',
];

export const AgentBuilder: FC<AgentBuilderProps> = ({
  spaceId,
  onBack,
  onCreated,
}) => {
  const [requirement, setRequirement] = useState(EXAMPLE_REQUIREMENTS[0]);
  const [spec, setSpec] = useState<AgentSpec>();
  const [resourcePlan, setResourcePlan] = useState<ResourcePlan>();
  const [warnings, setWarnings] = useState<string[]>([]);
  const [auditId, setAuditId] = useState<string>();
  const [generating, setGenerating] = useState(false);
  const [creating, setCreating] = useState(false);

  const canGenerate = requirement.trim().length > 0 && !generating;
  const canCreate = Boolean(spec) && !creating && !generating;

  const selectedSummary = useMemo(() => {
    const plugins = resourcePlan?.plugin_candidates?.filter(
      item => item.selected,
    );
    const workflows = resourcePlan?.workflow_candidates?.filter(
      item => item.selected,
    );
    const knowledge = resourcePlan?.knowledge_candidates?.filter(
      item => item.selected,
    );
    return {
      plugins: plugins?.length ?? 0,
      workflows: workflows?.length ?? 0,
      knowledge: knowledge?.length ?? 0,
    };
  }, [resourcePlan]);

  const handleGenerate = async () => {
    if (!canGenerate) {
      return;
    }
    setGenerating(true);
    try {
      const resp = await agentBuilderApi.GenerateSpec({
        space_id: spaceId,
        requirement: requirement.trim(),
      });
      setSpec(resp.data?.spec);
      setResourcePlan(resp.data?.resource_plan);
      setWarnings(resp.data?.warnings ?? []);
      setAuditId(resp.data?.audit_id);
      Toast.success('AgentSpec 已生成');
    } catch {
      Toast.error('生成失败，请稍后重试');
    } finally {
      setGenerating(false);
    }
  };

  const handleCreate = async () => {
    if (!spec || !canCreate) {
      return;
    }
    setCreating(true);
    try {
      const resp = await agentBuilderApi.CreateDraft({
        space_id: spaceId,
        audit_id: auditId,
        spec,
        resource_plan: resourcePlan,
      });
      const botId = resp.data?.bot_id || resp.data?.agent_id;
      if (!botId) {
        Toast.error('草稿创建成功但未返回智能体 ID');
        return;
      }
      Toast.success('智能体草稿已创建');
      onCreated?.(botId, resp.data?.redirect_url);
    } catch {
      Toast.error('创建草稿失败，请检查资源权限后重试');
    } finally {
      setCreating(false);
    }
  };

  return (
    <div className="h-full min-h-[calc(100vh-56px)] coz-bg-primary">
      <div className="flex flex-wrap items-center justify-between gap-[16px] px-[32px] py-[20px] border-0 border-b border-solid coz-stroke-primary">
        <div className="flex items-center gap-[12px]">
          <Button
            color="secondary"
            icon={<IconCozArrowLeft />}
            onClick={onBack}
          />
          <div>
            <div className="text-[20px] font-semibold coz-fg-primary">
              自然语言创建办公助手
            </div>
            <div className="mt-[4px] text-[13px] coz-fg-secondary">
              从办公需求生成 AgentSpec，并按厦航白名单推荐技能占位资源
            </div>
          </div>
        </div>
        <Button
          icon={<IconCozPlus />}
          loading={creating}
          disabled={!canCreate}
          onClick={handleCreate}
        >
          创建草稿
        </Button>
      </div>

      <div className="grid grid-cols-1 gap-[20px] px-[32px] py-[24px] xl:grid-cols-[minmax(360px,420px)_1fr]">
        <section className="rounded-[8px] border border-solid coz-stroke-primary coz-bg-plus p-[20px]">
          <div className="text-[16px] font-medium coz-fg-primary">办公需求</div>
          <TextArea
            className="mt-[16px]"
            rows={12}
            maxLength={1000}
            value={requirement}
            placeholder="描述你想创建的办公助手"
            onChange={value => setRequirement(value)}
          />
          <div className="mt-[16px] flex items-center gap-[12px]">
            <Button
              loading={generating}
              disabled={!canGenerate}
              onClick={handleGenerate}
            >
              生成 AgentSpec
            </Button>
            <Button
              color="secondary"
              disabled={generating}
              onClick={() => setRequirement(EXAMPLE_REQUIREMENTS[0])}
            >
              会议室示例
            </Button>
          </div>
          <div className="mt-[12px] flex flex-wrap gap-[8px]">
            {EXAMPLE_REQUIREMENTS.slice(1).map((item, index) => (
              <Button
                key={item}
                size="small"
                color="secondary"
                disabled={generating}
                onClick={() => setRequirement(item)}
              >
                {index === 0 ? '任务示例' : '周报示例'}
              </Button>
            ))}
          </div>
          {warnings.length ? (
            <div className="mt-[18px] space-y-[8px]">
              {warnings.map(item => (
                <div
                  key={item}
                  className="rounded-[6px] coz-mg-hglt-yellow p-[10px] text-[13px] coz-fg-primary"
                >
                  {item}
                </div>
              ))}
            </div>
          ) : null}
        </section>

        <Spin spinning={generating} wrapperClassName="min-h-[560px]">
          <div className="grid grid-cols-1 gap-[20px] 2xl:grid-cols-2">
            <SpecPreview spec={spec} />
            <ResourcePlanPreview
              resourcePlan={resourcePlan}
              selectedSummary={selectedSummary}
            />
          </div>
        </Spin>
      </div>
    </div>
  );
};

const SpecPreview: FC<{ spec?: AgentSpec }> = ({ spec }) => (
  <section className="rounded-[8px] border border-solid coz-stroke-primary coz-bg-plus p-[20px]">
    <div className="text-[16px] font-medium coz-fg-primary">AgentSpec</div>
    {spec ? (
      <div className="mt-[16px] space-y-[16px]">
        <InfoBlock title="名称" content={spec.name} />
        <InfoBlock title="场景类型" content={sceneTypeText(spec.scene_type)} />
        <InfoBlock title="目标" content={spec.goal} />
        <InfoBlock title="简介" content={spec.description} />
        <InfoBlock title="Prompt" content={spec.prompt} pre />
        <InfoBlock
          title="开场白"
          content={spec.onboarding?.prologue ?? ''}
        />
        <ListBlock
          title="建议问题"
          items={spec.onboarding?.suggested_questions ?? []}
        />
        <RequirementBlock requirements={spec.resource_requirements ?? []} />
      </div>
    ) : (
      <EmptyPreview text="生成后展示结构化 AgentSpec" />
    )}
  </section>
);

const ResourcePlanPreview: FC<{
  resourcePlan?: ResourcePlan;
  selectedSummary: { plugins: number; workflows: number; knowledge: number };
}> = ({ resourcePlan, selectedSummary }) => (
  <section className="rounded-[8px] border border-solid coz-stroke-primary coz-bg-plus p-[20px]">
    <div className="flex items-center justify-between">
      <div className="text-[16px] font-medium coz-fg-primary">资源规划</div>
      <div className="flex gap-[8px]">
        <Tag color="primary">插件 {selectedSummary.plugins}</Tag>
        <Tag color="green">工作流 {selectedSummary.workflows}</Tag>
        <Tag color="yellow">知识库 {selectedSummary.knowledge}</Tag>
      </div>
    </div>
    {resourcePlan ? (
      <div className="mt-[16px] space-y-[18px]">
        <CandidateGroup
          title="插件候选"
          candidates={resourcePlan.plugin_candidates ?? []}
        />
        <CandidateGroup
          title="工作流候选"
          candidates={resourcePlan.workflow_candidates ?? []}
        />
        <CandidateGroup
          title="知识库候选"
          candidates={resourcePlan.knowledge_candidates ?? []}
        />
        <MissingResources items={resourcePlan.missing_resources ?? []} />
        <RiskWarningBlock items={resourcePlan.risk_warnings ?? []} />
      </div>
    ) : (
      <EmptyPreview text="生成后展示资源映射结果" />
    )}
  </section>
);

const InfoBlock: FC<{ title: string; content?: string; pre?: boolean }> = ({
  title,
  content,
  pre,
}) => (
  <div>
    <div className="mb-[6px] text-[12px] font-medium coz-fg-secondary">
      {title}
    </div>
    <div
      className={[
        'rounded-[6px] coz-mg-secondary p-[10px] text-[13px] leading-[20px] coz-fg-primary',
        pre ? 'whitespace-pre-wrap max-h-[220px] overflow-auto' : '',
      ].join(' ')}
    >
      {content || '-'}
    </div>
  </div>
);

const ListBlock: FC<{ title: string; items: string[] }> = ({ title, items }) => (
  <div>
    <div className="mb-[6px] text-[12px] font-medium coz-fg-secondary">
      {title}
    </div>
    {items.length ? (
      <div className="space-y-[6px]">
        {items.map(item => (
          <div
            key={item}
            className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-primary"
          >
            {item}
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-secondary">
        -
      </div>
    )}
  </div>
);

const RequirementBlock: FC<{
  requirements: NonNullable<AgentSpec['resource_requirements']>;
}> = ({ requirements }) => (
  <div>
    <div className="mb-[6px] text-[12px] font-medium coz-fg-secondary">
      资源需求
    </div>
    {requirements.length ? (
      <div className="space-y-[8px]">
        {requirements.map(item => (
          <div
            key={`${item.type}-${item.name}-${item.intent}`}
            className="rounded-[6px] coz-mg-secondary p-[10px]"
          >
            <div className="flex items-center gap-[8px]">
              <Tag>{resourceTypeText(item.type)}</Tag>
              <span className="text-[13px] font-medium coz-fg-primary">
                {item.name || item.intent}
              </span>
            </div>
            <div className="mt-[6px] text-[13px] coz-fg-secondary">
              {item.intent}
            </div>
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-secondary">
        -
      </div>
    )}
  </div>
);

const CandidateGroup: FC<{
  title: string;
  candidates: ResourceCandidate[];
}> = ({ title, candidates }) => (
  <div>
    <div className="mb-[8px] text-[12px] font-medium coz-fg-secondary">
      {title}
    </div>
    {candidates.length ? (
      <div className="space-y-[8px]">
        {candidates.map(item => (
          <div
            key={`${item.type}-${item.id}`}
            className="rounded-[6px] border border-solid coz-stroke-primary p-[10px]"
          >
            <div className="flex items-start justify-between gap-[12px]">
              <div className="min-w-0">
                <div className="truncate text-[13px] font-medium coz-fg-primary">
                  {item.name}
                </div>
                {item.description ? (
                  <div className="mt-[4px] line-clamp-2 text-[12px] coz-fg-secondary">
                    {item.description}
                  </div>
                ) : null}
              </div>
              <Tag color={item.selected ? 'green' : 'primary'}>
                {item.selected ? '已选' : `${Math.round(item.score * 100)}%`}
              </Tag>
            </div>
            {item.reason ? (
              <div className="mt-[8px] text-[12px] coz-fg-secondary">
                {item.reason}
              </div>
            ) : null}
            <div className="mt-[8px] flex flex-wrap gap-[6px]">
              {item.system_name ? <Tag>{item.system_name}</Tag> : null}
              {item.template_key ? (
                <Tag color="primary">{item.template_key}</Tag>
              ) : null}
              {item.operation_type ? (
                <Tag color="yellow">{item.operation_type}</Tag>
              ) : null}
              {item.placeholder_status ? (
                <Tag color={item.placeholder_status === 'mapped' ? 'green' : 'yellow'}>
                  {item.placeholder_status === 'mapped' ? '已绑定资源' : '占位建议'}
                </Tag>
              ) : null}
            </div>
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-secondary">
        暂无匹配资源
      </div>
    )}
  </div>
);

const RiskWarningBlock: FC<{ items: RiskWarning[] }> = ({ items }) => (
  <div>
    <div className="mb-[8px] text-[12px] font-medium coz-fg-secondary">
      风险提示
    </div>
    {items.length ? (
      <div className="space-y-[8px]">
        {items.map(item => (
          <div
            key={`${item.code}-${item.related_resource}-${item.message}`}
            className="rounded-[6px] coz-mg-hglt-yellow p-[10px]"
          >
            <div className="flex flex-wrap items-center gap-[8px]">
              <Tag color={item.level === 'high' ? 'red' : 'yellow'}>
                {item.level}
              </Tag>
              <span className="text-[13px] font-medium coz-fg-primary">
                {item.code}
              </span>
              {item.related_resource ? (
                <span className="text-[12px] coz-fg-secondary">
                  {item.related_resource}
                </span>
              ) : null}
            </div>
            <div className="mt-[6px] text-[12px] coz-fg-secondary">
              {item.message}
            </div>
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-secondary">
        无
      </div>
    )}
  </div>
);

const MissingResources: FC<{ items: MissingResource[] }> = ({ items }) => (
  <div>
    <div className="mb-[8px] text-[12px] font-medium coz-fg-secondary">
      缺失资源建议
    </div>
    {items.length ? (
      <div className="space-y-[8px]">
        {items.map(item => (
          <div
            key={`${item.type}-${item.name}-${item.intent}`}
            className="rounded-[6px] coz-mg-hglt-yellow p-[10px]"
          >
            <div className="flex items-center gap-[8px]">
              <Tag color="yellow">{resourceTypeText(item.type)}</Tag>
              <span className="text-[13px] font-medium coz-fg-primary">
                {item.name || item.intent}
              </span>
            </div>
            <div className="mt-[6px] text-[12px] coz-fg-secondary">
              {item.suggestion}
            </div>
          </div>
        ))}
      </div>
    ) : (
      <div className="rounded-[6px] coz-mg-secondary px-[10px] py-[8px] text-[13px] coz-fg-secondary">
        无
      </div>
    )}
  </div>
);

const EmptyPreview: FC<{ text: string }> = ({ text }) => (
  <div className="mt-[16px] flex h-[420px] items-center justify-center rounded-[8px] border border-dashed coz-stroke-primary text-[13px] coz-fg-secondary">
    {text}
  </div>
);

const resourceTypeText = (type: string) => {
  if (type === 'plugin') {
    return '插件';
  }
  if (type === 'workflow') {
    return '工作流';
  }
  if (type === 'knowledge') {
    return '知识库';
  }
  return type;
};

const sceneTypeText = (sceneType?: string) => {
  if (sceneType === 'meeting_room_booking') {
    return '会议室自动预订助手';
  }
  if (sceneType === 'task_followup') {
    return '个人任务跟进助手';
  }
  if (sceneType === 'project_weekly_report') {
    return '项目周报与摘要助手';
  }
  return sceneType || '通用办公助手';
};

export default AgentBuilder;
