import { useNavigate, useParams } from 'react-router-dom';

import { AgentBuilder } from '@coze-studio/workspace-adapter/agent-builder';

export default function AgentBuilderPage() {
  const { space_id = '' } = useParams<{ space_id: string }>();
  const navigate = useNavigate();

  if (!space_id) {
    return null;
  }

  return (
    <AgentBuilder
      spaceId={space_id}
      onBack={() => navigate(`/space/${space_id}/develop`)}
      onCreated={(botId, redirectURL) => {
        navigate(redirectURL || `/space/${space_id}/bot/${botId}`);
      }}
    />
  );
}
